// ======================================================================
// Policy struct
// ======================================================================

type StaticLiftListPolicy struct {
	// NL→IR Item C1 Path A: the current event's typed `_event.data` payload,
	// lifted from the dequeued event by PopulateEventMetadata and read by the
	// native transition guards (`p.pending<Event>Payload.<field>`). Mirrors
	// the Rust policy's `pending_payload` / the C11 `sm->pending_payload`.
	pendingPayloadTag StaticLiftListPayloadTag
	pendingTextGivenPayload StaticLiftListTextGivenPayload

	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `answer` datamodel variable, published (`sce:direction="out"`).
	vAnswer optional.Of[StaticLiftListPlanRecord]
	// W3C SCXML 5.2: the `why` datamodel variable, published (`sce:direction="out"`).
	vWhy optional.Of[StaticLiftListLiftRefusalRecord]
	// W3C SCXML 5.2: the `lifts` datamodel variable, published (`sce:direction="out"`).
	vLifts uint32
	// W3C SCXML 5.2: the `errors` datamodel variable, published (`sce:direction="out"`).
	vErrors uint32
	// W3C SCXML 5.2: the `priority` datamodel variable, published (`sce:direction="out"`).
	vPriority uint8
	// W3C SCXML 5.2: the `held_items` datamodel variable, published (`sce:direction="out"`).
	vHeldItems uint32
	// W3C SCXML 5.2: the `weeks` datamodel variable, published (`sce:direction="out"`).
	vWeeks uint32
	// W3C SCXML 5.2: the `other_reads` datamodel variable, published (`sce:direction="out"`).
	vOtherReads uint32
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// W3C SCXML C.1: the id of the session that invoked this one, whose
	// published location reaches it as `#_parent` does (docs/adr/0090); empty
	// for a session its host started.
	ParentSessionID    string
	// §scxml-6.4: the values an invoking session handed this machine before
	// its start, by name; its start takes them, each as the initial value of
	// the top-level `<data>` it names (docs/adr/0098).
	handedValues       map[string]interface{}
}

// NewStaticLiftListPolicy creates a new policy with default values.
func NewStaticLiftListPolicy() StaticLiftListPolicy {
	var vAnswer optional.Of[StaticLiftListPlanRecord] = optional.None[StaticLiftListPlanRecord]()
	var vWhy optional.Of[StaticLiftListLiftRefusalRecord] = optional.None[StaticLiftListLiftRefusalRecord]()
	var vLifts uint32 = 0
	var vErrors uint32 = 0
	var vPriority uint8 = 0
	var vHeldItems uint32 = 0
	var vWeeks uint32 = 0
	var vOtherReads uint32 = 0
	return StaticLiftListPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vAnswer: vAnswer,
		vWhy: vWhy,
		vLifts: vLifts,
		vErrors: vErrors,
		vPriority: vPriority,
		vHeldItems: vHeldItems,
		vWeeks: vWeeks,
		vOtherReads: vOtherReads,
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticLiftListPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

// Answer reports what the published `answer` datamodel
