// StaticLiftListInvokeParams holds the values a parent's `<param>` and
// `namelist` give this machine's variables before it starts (§scxml-6.4.1). A
// variable left nil, or absent for an optional one, keeps the value its `<data>`
// gave it.
type StaticLiftListInvokeParams struct {
	VLifts *uint32
	VErrors *uint32
	VPriority *uint8
	VHeldItems *uint32
	VWeeks *uint32
	VOtherReads *uint32
}

// AcceptParams gives this machine the values handed carries, each as the
// initial value of its variable in place of the one its `<data>` gives, so
// that a variable declared after it whose initial value reads it reads the
// handed value (§scxml-6.4, docs/adr/0098). Called before it initializes.
func (p *StaticLiftListPolicy) AcceptParams(handed StaticLiftListInvokeParams) {
	var vAnswer optional.Of[StaticLiftListPlanRecord] = optional.None[StaticLiftListPlanRecord]()
	var vWhy optional.Of[StaticLiftListLiftRefusalRecord] = optional.None[StaticLiftListLiftRefusalRecord]()
	var vLifts uint32
	if handed.VLifts != nil {
		vLifts = *handed.VLifts
	} else {
		vLifts = 0
	}
	var vErrors uint32
	if handed.VErrors != nil {
		vErrors = *handed.VErrors
	} else {
		vErrors = 0
	}
	var vPriority uint8
	if handed.VPriority != nil {
		vPriority = *handed.VPriority
	} else {
		vPriority = 0
	}
	var vHeldItems uint32
	if handed.VHeldItems != nil {
		vHeldItems = *handed.VHeldItems
	} else {
		vHeldItems = 0
	}
	var vWeeks uint32
	if handed.VWeeks != nil {
		vWeeks = *handed.VWeeks
	} else {
		vWeeks = 0
	}
	var vOtherReads uint32
	if handed.VOtherReads != nil {
		vOtherReads = *handed.VOtherReads
	} else {
		vOtherReads = 0
	}
	p.vAnswer = vAnswer
	p.vWhy = vWhy
	p.vLifts = vLifts
	p.vErrors = vErrors
	p.vPriority = vPriority
	p.vHeldItems = vHeldItems
	p.vWeeks = vWeeks
	p.vOtherReads = vOtherReads
}



// No script engine needed for this state machine, so it has no script session
// to fail and its start is never refused for one.
func (p *StaticLiftListPolicy) InitializeDataModel(eng *sce.Engine[StaticLiftListState, StaticLiftListEvent]) *sce.ScriptSessionFailure {
	return nil
}

// SetParamValueInScriptEngine is a no-op for state machines without script engine.
func (p *StaticLiftListPolicy) SetParamValueInScriptEngine(name string, value interface{}) {}


// ExecutePendingInvokes is a no-op (no invokes in this SM).
func (p *StaticLiftListPolicy) ExecutePendingInvokes(engine *sce.Engine[StaticLiftListState, StaticLiftListEvent]) {}

// TickChildren is a no-op (no invokes in this SM).
func (p *StaticLiftListPolicy) TickChildren(engine *sce.Engine[StaticLiftListState, StaticLiftListEvent]) {}

// DeliverToParent delivers a delayed `<send target="#_parent">` whose wait is
// over, with the payload an immediate one carries (W3C SCXML 6.2 + 6.4). It
// waited in this machine's own queue, so `<cancel>` reached it and a child that
// ended first dropped it — the engine dispatches nothing once final. Emitted for
// every machine, since the one that needs it is an invoked child, which need not
// invoke anything itself.
func (p *StaticLiftListPolicy) DeliverToParent(eventName, eventData string) bool {
	if p.ParentExternalQueue == nil {
		return false
	}
	p.ParentExternalQueue.Push(sce.ParentEvent{Name: eventName, Data: eventData})
	return true
}

// HasParentSession answers whether a session invoked this one (W3C SCXML C.1):
// the queue the invoking parent installs is the link to it.
func (p *StaticLiftListPolicy) HasParentSession() bool {
	return p.ParentExternalQueue != nil
}

// IsParentSession answers whether sessionID names the session that invoked this
// one (W3C SCXML C.1): the location it publishes is a target, so a reply sent to
// the origin of an event the parent sent reaches it (docs/adr/0090).
func (p *StaticLiftListPolicy) IsParentSession(sessionID string) bool {
	return p.ParentExternalQueue != nil && sessionID != "" && p.ParentSessionID == sessionID
}

